import mlflow

@mlflow.trace(span_type="AGENT")
def handle(request):
    user = auth.lookup(request.token)             # only known here
    mlflow.update_current_trace(
        tags={"tenant": user.tenant, "plan": user.plan},
        metadata={"request_id": request.id},
    )
    return agent.invoke({"messages": request.messages})

buffers: dict[str, str] = {}
for msg, meta in graph.stream(inp, config, stream_mode="messages"):
    if meta.get("langgraph_node") != "agent":
        continue                                  # skip tool/summary nodes
    buffers[msg.id] = buffers.get(msg.id, "") + (msg.text or "")
    ui.render(msg.id, buffers[msg.id])            # upsert by id

cursor = None
while True:
    page = client.list_runs(limit=100, cursor=cursor)   # any cursor API
    for item in page["items"]:
        handle(item)
    cursor = page.get("next_cursor")
    if not cursor:
        break
